        V("alinlangan-l37", "álinlangan", "doubt", say="A-lin-la-ngan", pos="noun", group="labels"),
        V("paluin-m37", "paluin", "beat", pos="verb", group="more", note="From: Gustó mong paluin kitá? = Do you want me to beat you?"),
        V("magpaulan-m37", "magpaulán", "get caught in the rain", say="mag-pa-u-LAN", pos="verb", group="more", note="From: Huwág kang magpaulán = Don't get caught in the rain."),
        V("kanin-m37", "kanin", "eat", pos="verb", group="more", note="From: Huwág mong kanin iyán = Don't eat that. Lesson 15 prints kánin (to eat)."),
